WITH flattened_attrs AS (SELECT id, plan, effective_from, currency, tier_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT id, currency, entry_price, SUM(entry_price) OVER (PARTITION BY currency ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_entry_price, NTILE(10) OVER (PARTITION BY currency ORDER BY entry_price DESC, id) AS entry_price_bucket, DENSE_RANK() OVER (PARTITION BY currency, plan ORDER BY entry_price DESC NULLS FIRST) AS entry_price_dense_rank, SUM(entry_price) OVER (PARTITION BY currency, plan ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_entry_price_2, LAG(entry_price, 1) OVER (PARTITION BY currency ORDER BY entry_price, id) AS prev_entry_price FROM flattened_attrs WHERE plan = 'enterprise';
